{
  "name": "Car Insurance Claim Handling Process",
  "resources": [
    {
      "name": "Customer",
      "capacity": 1,
      "resource_type": "external_party"
    },
    {
      "name": "Notification Department",
      "capacity": 1,
      "resource_type": "department"
    },
    {
      "name": "Handling Department",
      "capacity": 1,
      "resource_type": "department"
    },
    {
      "name": "Garage",
      "capacity": 1,
      "resource_type": "external_party"
    }
  ],
  "events": [
    {
      "id": "event_cust_start",
      "name": "Claim needed",
      "event_position": "start",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_cust_send",
      "name": "Claim submitted",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Claim Documentation"
    },
    {
      "id": "event_notif_start",
      "name": "Claim received",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Claim Documentation"
    },
    {
      "id": "event_notif_end",
      "name": "Claim registered",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Registered Claim"
    },
    {
      "id": "event_hand_start",
      "name": "Claim picked up",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Registered Claim"
    },
    {
      "id": "event_hand_send_letter",
      "name": "Letter sent to customer",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Decision Letter"
    },
    {
      "id": "event_cust_receive_letter",
      "name": "Letter received",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Decision Letter"
    },
    {
      "id": "event_cust_end",
      "name": "Process finished for customer",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_hand_end",
      "name": "Process completed",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    }
  ],
  "tasks": [
    {
      "id": "task_cust_submit",
      "name": "Submit claim and relevant documentation",
      "bpmn_type": "bpmn:Task",
      "resource_name": "Customer",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": ["data_doc"]
    },
    {
      "id": "task_notif_check",
      "name": "Check documents upon completeness",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Notification Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["data_doc"],
      "output_data_ids": []
    },
    {
      "id": "task_notif_register",
      "name": "Register claim",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Notification Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": ["data_claim"]
    },
    {
      "id": "task_hand_check_ins",
      "name": "Check insurance",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Handling Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["data_claim"],
      "output_data_ids": []
    },
    {
      "id": "task_hand_assess",
      "name": "Perform assessment",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Handling Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["data_claim"],
      "output_data_ids": []
    },
    {
      "id": "task_hand_phone_garage",
      "name": "Phone garage to authorise repairs",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "Handling Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_hand_sched_pay",
      "name": "Schedule payment",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Handling Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_hand_reject",
      "name": "Reject claim",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Handling Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_hand_prepare_letter",
      "name": "Prepare decision letter",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Handling Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": ["data_letter"]
    }
  ],
  "gateways": [
    {
      "id": "gtw_assess",
      "name": "Assessment positive?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "sf_pos",
          "condition": "Positive"
        },
        {
          "flow_id": "sf_neg",
          "condition": "Negative"
        }
      ]
    },
    {
      "id": "gtw_join",
      "name": "Merge paths",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": null
    }
  ],
  "sequence_flows": [
    {
      "id": "sf_c1",
      "source_id": "event_cust_start",
      "target_id": "task_cust_submit",
      "condition_name": null
    },
    {
      "id": "sf_c2",
      "source_id": "task_cust_submit",
      "target_id": "event_cust_send",
      "condition_name": null
    },
    {
      "id": "sf_c3",
      "source_id": "event_cust_receive_letter",
      "target_id": "event_cust_end",
      "condition_name": null
    },
    {
      "id": "sf_n1",
      "source_id": "event_notif_start",
      "target_id": "task_notif_check",
      "condition_name": null
    },
    {
      "id": "sf_n2",
      "source_id": "task_notif_check",
      "target_id": "task_notif_register",
      "condition_name": null
    },
    {
      "id": "sf_n3",
      "source_id": "task_notif_register",
      "target_id": "event_notif_end",
      "condition_name": null
    },
    {
      "id": "sf_h1",
      "source_id": "event_hand_start",
      "target_id": "task_hand_check_ins",
      "condition_name": null
    },
    {
      "id": "sf_h2",
      "source_id": "task_hand_check_ins",
      "target_id": "task_hand_assess",
      "condition_name": null
    },
    {
      "id": "sf_h3",
      "source_id": "task_hand_assess",
      "target_id": "gtw_assess",
      "condition_name": null
    },
    {
      "id": "sf_pos",
      "source_id": "gtw_assess",
      "target_id": "task_hand_phone_garage",
      "condition_name": "Positive"
    },
    {
      "id": "sf_h4",
      "source_id": "task_hand_phone_garage",
      "target_id": "task_hand_sched_pay",
      "condition_name": null
    },
    {
      "id": "sf_h5",
      "source_id": "task_hand_sched_pay",
      "target_id": "gtw_join",
      "condition_name": null
    },
    {
      "id": "sf_neg",
      "source_id": "gtw_assess",
      "target_id": "task_hand_reject",
      "condition_name": "Negative"
    },
    {
      "id": "sf_h6",
      "source_id": "task_hand_reject",
      "target_id": "gtw_join",
      "condition_name": null
    },
    {
      "id": "sf_h7",
      "source_id": "gtw_join",
      "target_id": "task_hand_prepare_letter",
      "condition_name": null
    },
    {
      "id": "sf_h8",
      "source_id": "task_hand_prepare_letter",
      "target_id": "event_hand_send_letter",
      "condition_name": null
    },
    {
      "id": "sf_h9",
      "source_id": "event_hand_send_letter",
      "target_id": "event_hand_end",
      "condition_name": null
    }
  ],
  "pools": [
    {
      "id": "pool_customer",
      "name": "Customer",
      "element_ids": [
        "event_cust_start",
        "task_cust_submit",
        "event_cust_send",
        "event_cust_receive_letter",
        "event_cust_end"
      ]
    },
    {
      "id": "pool_notification",
      "name": "Notification Department",
      "element_ids": [
        "event_notif_start",
        "task_notif_check",
        "task_notif_register",
        "event_notif_end"
      ]
    },
    {
      "id": "pool_handling",
      "name": "Handling Department",
      "element_ids": [
        "event_hand_start",
        "task_hand_check_ins",
        "task_hand_assess",
        "gtw_assess",
        "task_hand_phone_garage",
        "task_hand_sched_pay",
        "task_hand_reject",
        "gtw_join",
        "task_hand_prepare_letter",
        "event_hand_send_letter",
        "event_hand_end"
      ]
    }
  ],
  "message_flows": [
    {
      "id": "mf_cust_to_notif",
      "source_id": "event_cust_send",
      "target_id": "event_notif_start",
      "name": "Claim Documentation"
    },
    {
      "id": "mf_notif_to_hand",
      "source_id": "event_notif_end",
      "target_id": "event_hand_start",
      "name": "Registered Claim"
    },
    {
      "id": "mf_hand_to_cust",
      "source_id": "event_hand_send_letter",
      "target_id": "event_cust_receive_letter",
      "name": "Decision Letter"
    }
  ],
  "data_objects": [
    {
      "id": "data_doc",
      "name": "Relevant Documentation"
    },
    {
      "id": "data_claim",
      "name": "Claim Record"
    },
    {
      "id": "data_letter",
      "name": "Decision Letter"
    }
  ],
  "data_stores": [],
  "inter_arrival_time": {
    "distribution": "fixed",
    "value": 1.0,
    "unit": "minutes",
    "is_placeholder": true,
    "source": "default_missing_duration"
  },
  "simulation_duration": null,
  "simulation_duration_unit": "hours"
}
